  "after_record" TEXT NOT NULL,
  "provider_record_id" TEXT,
  "observed_record" TEXT,
  "owned" INTEGER NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "last_error_code" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (plan_id, ordinal),
  FOREIGN KEY (tenant_id, plan_id) REFERENCES dns_change_plans(tenant_id, id),
  CHECK (kind IN ('create', 'update')),
  CHECK (status IN ('pending', 'submitted', 'applied', 'uncertain', 'rolled_back'))
);

CREATE TABLE IF NOT EXISTS "dns_zone_versions" (
  "domain" TEXT NOT NULL,
  "content_hash" TEXT NOT NULL,
  "serial" INTEGER NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("domain"),
  CHECK (length(content_hash) = 64),
  CHECK (serial >= 0 AND serial < 4294967296)
);

CREATE TABLE IF NOT EXISTS "domain_dns_security" (
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "dnssec_enabled" INTEGER NOT NULL DEFAULT 0,
  "secondary_hostname" TEXT NOT NULL DEFAULT '',
  "secondary_address" TEXT NOT NULL DEFAULT '',
  "primary_address" TEXT NOT NULL DEFAULT '',
  "tsig_key_name" TEXT NOT NULL DEFAULT '',
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "domain_id"),
  FOREIGN KEY (tenant_id, domain_id) REFERENCES domains(tenant_id, id),
  CHECK (length(secondary_hostname) <= 253 AND length(secondary_address) <= 64 AND length(primary_address) <= 64 AND length(tsig_key_name) <= 128),
  CHECK (secondary_hostname = ''AND secondary_address = ''AND primary_address = ''AND tsig_key_name = ''OR secondary_hostname <> ''AND secondary_address <> ''AND primary_address <> ''AND tsig_key_name <> '')
);

CREATE TABLE IF NOT EXISTS "domain_tls_reports" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "report_digest" TEXT NOT NULL,
  "reporter_digest" TEXT NOT NULL,
  "report_id_digest" TEXT NOT NULL,
  "period_start" INTEGER NOT NULL,
  "period_end" INTEGER NOT NULL,
  "successful" INTEGER NOT NULL,
  "failed" INTEGER NOT NULL,
  "failures" TEXT NOT NULL,
  "received_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "source_verified" INTEGER NOT NULL DEFAULT 0,
  UNIQUE (tenant_id, domain_id, reporter_digest, report_id_digest, period_start, period_end),
  FOREIGN KEY (tenant_id, domain_id) REFERENCES domains(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (period_end >= period_start AND period_end <= (period_start + '8 days')),
  CHECK (failed >= 0 AND failed <= 1000000000),
  CHECK (length(report_digest) = 64),
  CHECK (length(report_id_digest) = 64),
  CHECK (length(reporter_digest) = 64),
  CHECK (NOT source_verified),
  CHECK (successful >= 0 AND successful <= 1000000000)
);

CREATE TABLE IF NOT EXISTS "domain_transport_security" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "mtasts_policy_id" TEXT NOT NULL,
  "mtasts_mode" TEXT NOT NULL DEFAULT 'testing',
  "tls_rpt_rua" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "enabled" INTEGER NOT NULL DEFAULT 0,
  "policy_mx" TEXT NOT NULL DEFAULT '[]',
  "max_age" INTEGER NOT NULL DEFAULT 86400,
  "published_at" INTEGER,
  "testing_since" INTEGER,
  "cache_safe_after" INTEGER,
  "observation_digest" TEXT,
  "observed_at" INTEGER,
  "observation_status" TEXT NOT NULL DEFAULT 'unverified',
  "observation_detail" TEXT NOT NULL DEFAULT '[]',
  "version" INTEGER NOT NULL DEFAULT 1,
  UNIQUE (tenant_id, domain_id),
  FOREIGN KEY (domain_id) REFERENCES domains(id),
  FOREIGN KEY (tenant_id, domain_id) REFERENCES domains(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (max_age >= 300 AND max_age <= 604800),
  CHECK (mtasts_mode IN ('enforce', 'testing', 'none')),
  CHECK (length(trim(mtasts_policy_id)) >= 1 AND length(trim(mtasts_policy_id)) <= 32),
  CHECK (length(trim(tls_rpt_rua)) >= 3 AND length(trim(tls_rpt_rua)) <= 320)
);

CREATE TABLE IF NOT EXISTS "domains" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "fqdn" TEXT NOT NULL,
  "mode" TEXT NOT NULL DEFAULT 'delegated',
  "status" TEXT NOT NULL DEFAULT 'pending_dns',
  "dns_provider" TEXT,
  "provider_ref" TEXT,
  "verification_token" TEXT NOT NULL,
  "verified_at" INTEGER,
  "mx_host" TEXT,
  "tls_mode" TEXT NOT NULL DEFAULT 'letsencrypt',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "dkim_selector" TEXT NOT NULL DEFAULT 'mail',
  "dkim_private_key" TEXT,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "verification_issued_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "verification_expires_at" INTEGER NOT NULL DEFAULT ((CAST(strftime('%s','now') AS INTEGER)*1000000) + 604800*1000000),
  "provisioning_state" TEXT NOT NULL DEFAULT 'ready',
  "dns_explicit" INTEGER NOT NULL DEFAULT 0,
  "custom_web_enabled" INTEGER NOT NULL DEFAULT 1,
  UNIQUE (fqdn),
  UNIQUE (id, tenant_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (status <> 'active'OR verified_at IS NOT NULL),
  CHECK (verification_expires_at > verification_issued_at),
  CHECK (mode IN ('managed', 'delegated')),
  CHECK (provisioning_state IN ('pending', 'ready', 'blocked')),
  CHECK (status IN ('pending_dns', 'active', 'failed', 'disabled'))
);

CREATE TABLE IF NOT EXISTS "mailbox_addressbooks" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "version" INTEGER NOT NULL DEFAULT 1,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "deleted_at" INTEGER,
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(trim(name)) >= 1 AND length(trim(name)) <= 200),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_ai_chunks" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "folder" TEXT NOT NULL,
  "folder_uidvalidity" INTEGER NOT NULL,
  "message_uid" INTEGER NOT NULL,
  "chunk_index" INTEGER NOT NULL,
  "content_version" INTEGER NOT NULL,
  "content" TEXT NOT NULL,
  "content_digest" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, folder, folder_uidvalidity, message_uid, chunk_index),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (chunk_index >= 0),
  CHECK (length(content) >= 1 AND length(content) <= 2000),
  CHECK (content_version >= 1),
  CHECK (length(folder) >= 1 AND length(folder) <= 500),
  CHECK (folder_uidvalidity >= 1 AND folder_uidvalidity <= 4294967295),
  CHECK (message_uid >= 1 AND message_uid <= 4294967295)
);

CREATE TABLE IF NOT EXISTS "mailbox_ai_drafts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "subject" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(body) >= 1 AND length(body) <= 20000),
  CHECK (length(subject) >= 1 AND length(subject) <= 200 AND instr(subject, ' ') = 0),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_ai_phishing_findings" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "folder" TEXT NOT NULL,
  "uid_validity" INTEGER NOT NULL,
  "uid" INTEGER NOT NULL,
  "input_digest" TEXT NOT NULL,
  "result" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (mailbox_id, folder, uid_validity, uid),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(folder) >= 1 AND length(folder) <= 1024),
  CHECK (uid >= 1 AND uid <= 4294967295),
  CHECK (uid_validity >= 1 AND uid_validity <= 4294967295)
);

CREATE TABLE IF NOT EXISTS "mailbox_aliases" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "local_part" TEXT NOT NULL,
  "target" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'alias',
  "active" INTEGER NOT NULL DEFAULT 1,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "sender_logins" TEXT NOT NULL DEFAULT '[]',
  FOREIGN KEY (domain_id, tenant_id) REFERENCES domains(id, tenant_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (kind IN ('alias', 'catchall', 'forward'))
);

CREATE TABLE IF NOT EXISTS "mailbox_calendars" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "timezone" TEXT NOT NULL DEFAULT 'UTC',
  "color" TEXT NOT NULL DEFAULT '',
  "version" INTEGER NOT NULL DEFAULT 1,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "deleted_at" INTEGER,
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(color) <= 16),
  CHECK (length(trim(name)) >= 1 AND length(trim(name)) <= 200),
  CHECK (length(timezone) >= 1 AND length(timezone) <= 100),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_changes" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "resource_type" TEXT NOT NULL,
  "resource_id" INTEGER NOT NULL,
  "version" INTEGER NOT NULL,
  "deleted" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (resource_id > 0),
  CHECK (resource_type IN ('addressbook', 'contact', 'calendar', 'event')),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_contact_group_members" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "group_id" INTEGER NOT NULL,
  "contact_id" INTEGER NOT NULL,
  PRIMARY KEY ("tenant_id", "mailbox_id", "group_id", "contact_id"),
  FOREIGN KEY (tenant_id, mailbox_id, contact_id) REFERENCES mailbox_contacts(tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id, group_id) REFERENCES mailbox_contact_groups(tenant_id, mailbox_id, id)
);

CREATE TABLE IF NOT EXISTS "mailbox_contact_groups" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "addressbook_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "deleted_at" INTEGER,
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id, addressbook_id) REFERENCES mailbox_addressbooks(tenant_id, mailbox_id, id),
  CHECK (length(trim(name)) >= 1 AND length(trim(name)) <= 100)
);

CREATE TABLE IF NOT EXISTS "mailbox_contacts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "addressbook_id" INTEGER NOT NULL,
  "version" INTEGER NOT NULL DEFAULT 1,
  "display_name" TEXT NOT NULL DEFAULT '',
  "given_name" TEXT NOT NULL DEFAULT '',
  "family_name" TEXT NOT NULL DEFAULT '',
  "emails" TEXT NOT NULL DEFAULT '[]',
  "phones" TEXT NOT NULL DEFAULT '[]',
  "note" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "deleted_at" INTEGER,
  "organization" TEXT NOT NULL DEFAULT '',
  "job_title" TEXT NOT NULL DEFAULT '',
  "addresses" TEXT NOT NULL DEFAULT '[]',
  "birthday" TEXT NOT NULL DEFAULT '',
  "photo" TEXT NOT NULL DEFAULT '',
  "vcard_extra" TEXT NOT NULL DEFAULT '[]',
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id, addressbook_id) REFERENCES mailbox_addressbooks(tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(birthday) <= 32),
  CHECK (length(display_name) <= 200),
  CHECK (length(family_name) <= 100),
  CHECK (length(given_name) <= 100),
  CHECK (length(job_title) <= 200),
  CHECK (length(note) <= 4000),
  CHECK (length(organization) <= 200),
  CHECK (length(photo) <= 65536),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_eas_collection_state" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "device_id" TEXT NOT NULL,
  "folder_id" TEXT NOT NULL,
  "sync_epoch" INTEGER NOT NULL DEFAULT 1,
  "change_seq" INTEGER NOT NULL DEFAULT 0,
  "uid_validity" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, device_id, folder_id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (change_seq >= 0),
  CHECK (length(device_id) >= 1 AND length(device_id) <= 200),
  CHECK (length(folder_id) >= 1 AND length(folder_id) <= 300),
  CHECK (sync_epoch >= 1),
  CHECK (uid_validity >= 0)
);

CREATE TABLE IF NOT EXISTS "mailbox_eas_devices" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "device_id" TEXT NOT NULL,
  "protocol_version" TEXT NOT NULL,
  "user_agent" TEXT NOT NULL DEFAULT '',
  "policy_key" INTEGER NOT NULL DEFAULT 0,
  "provisioned" INTEGER NOT NULL DEFAULT 0,
  "last_seen_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "ping_heartbeat" INTEGER NOT NULL DEFAULT 0,
  "ping_folders" TEXT NOT NULL DEFAULT '[]',
  UNIQUE (tenant_id, mailbox_id, device_id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(device_id) >= 1 AND length(device_id) <= 200),
  CHECK (json_type(ping_folders) = 'array'AND json_array_length(ping_folders) <= 100),
  CHECK (ping_heartbeat >= 0 AND ping_heartbeat <= 3600),
  CHECK (policy_key >= 0),
  CHECK (protocol_version IN ('12.1', '14.0', '14.1', '16.0', '16.1')),
  CHECK (length(user_agent) <= 200)
);

CREATE TABLE IF NOT EXISTS "mailbox_eas_folder_state" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "device_id" TEXT NOT NULL,
  "folder_id" TEXT NOT NULL,
  "parent_id" TEXT NOT NULL DEFAULT '',
  "display_name" TEXT NOT NULL DEFAULT '',
  "folder_type" INTEGER NOT NULL,
  "folder_class" TEXT NOT NULL DEFAULT '',
  "change_seq" INTEGER NOT NULL,
  UNIQUE (tenant_id, mailbox_id, device_id, folder_id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(device_id) >= 1 AND length(device_id) <= 200),
  CHECK (length(display_name) <= 200),
  CHECK (folder_class IN ('', 'Email', 'Calendar', 'Contacts')),
  CHECK (length(folder_id) >= 1 AND length(folder_id) <= 300),
  CHECK (folder_type >= 1 AND folder_type <= 20),
  CHECK (length(parent_id) <= 300)
);

CREATE TABLE IF NOT EXISTS "mailbox_eas_item_state" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "device_id" TEXT NOT NULL,
  "folder_id" TEXT NOT NULL,
  "item_id" TEXT NOT NULL,
  "fingerprint" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("tenant_id", "mailbox_id", "device_id", "folder_id", "item_id"),
  CHECK (length(device_id) >= 1 AND length(device_id) <= 200),
  CHECK (length(fingerprint) <= 300),
  CHECK (length(folder_id) >= 1 AND length(folder_id) <= 300),
  CHECK (length(item_id) >= 1 AND length(item_id) <= 300)
);

CREATE TABLE IF NOT EXISTS "mailbox_events" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "calendar_id" INTEGER NOT NULL,
  "uid" TEXT NOT NULL,
  "version" INTEGER NOT NULL DEFAULT 1,
  "sequence" INTEGER NOT NULL DEFAULT 0,
  "summary" TEXT NOT NULL DEFAULT '',
  "description" TEXT NOT NULL DEFAULT '',
  "location" TEXT NOT NULL DEFAULT '',
  "starts_at" INTEGER NOT NULL,
  "ends_at" INTEGER NOT NULL,
  "all_day" INTEGER NOT NULL DEFAULT 0,
  "timezone" TEXT NOT NULL DEFAULT 'UTC',
  "rrule" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'confirmed',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "deleted_at" INTEGER,
  "attendees" TEXT NOT NULL DEFAULT '[]',
  "recurrence_overrides" TEXT NOT NULL DEFAULT '[]',
  "organizer" TEXT NOT NULL DEFAULT '',
  "invitation_sequence" INTEGER NOT NULL DEFAULT 0,
  "invitation_stamp" INTEGER,
  "invitation_digest" TEXT NOT NULL DEFAULT '',
  "invitation_response" TEXT NOT NULL DEFAULT '',
  "reminders" TEXT NOT NULL DEFAULT '[]',
  "reminder_scanned_at" INTEGER NOT NULL DEFAULT '1970-01-01 00:00:00+00',
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id, calendar_id) REFERENCES mailbox_calendars(tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (json_type(attendees) = 'array'AND json_array_length(attendees) <= 20),
  CHECK (ends_at > starts_at),
  CHECK (length(description) <= 8000),
  CHECK (length(invitation_digest) IN (0, 64)),
  CHECK (invitation_response IN ('', 'needs-action', 'accepted', 'declined', 'tentative')),
  CHECK (invitation_sequence >= 0),
  CHECK (length(location) <= 500),
  CHECK (json_type(recurrence_overrides) = 'array'AND json_array_length(recurrence_overrides) <= 400),
  CHECK (json_type(reminders) = 'array'AND json_array_length(reminders) <= 5),
  CHECK (length(rrule) <= 500),
  CHECK (sequence >= 0),
  CHECK (status IN ('confirmed', 'tentative', 'cancelled')),
  CHECK (length(summary) <= 500),
  CHECK (length(timezone) >= 1 AND length(timezone) <= 100),
  CHECK (length(uid) >= 1 AND length(uid) <= 255),
  CHECK (version >= 1)
);

CREATE TABLE IF NOT EXISTS "mailbox_import_items" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "job_id" INTEGER NOT NULL,
  "item_index" INTEGER NOT NULL,
  "subject" TEXT NOT NULL DEFAULT '',
  "message_id" TEXT NOT NULL DEFAULT '',
  "raw_sha256" TEXT NOT NULL DEFAULT '',
  "raw_bytes" INTEGER NOT NULL DEFAULT 0,
  "raw_secret" TEXT NOT NULL DEFAULT '',
  "selected" INTEGER NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL,
  "error_code" TEXT NOT NULL DEFAULT '',
  "duplicate_of" INTEGER NOT NULL DEFAULT 0,
  "baseline_uids" TEXT NOT NULL DEFAULT '[]',
  "destination_uid" INTEGER,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "attempt_started_at" INTEGER,
  "reconciled_at" INTEGER,
  "reconcile_absent" INTEGER NOT NULL DEFAULT 0,
  "review_reason" TEXT NOT NULL DEFAULT '',
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "mailbox_id", "job_id", "item_index"),
  FOREIGN KEY (tenant_id, mailbox_id, job_id) REFERENCES mailbox_import_jobs(tenant_id, mailbox_id, id) ON DELETE CASCADE,
  CHECK (attempts >= 0 AND attempts <= 20),
  CHECK (destination_uid >= 1 AND destination_uid <= 4294967295),
  CHECK (duplicate_of >= 0 AND duplicate_of <= 100),
  CHECK (length(error_code) <= 128),
  CHECK (item_index >= 1 AND item_index <= 100),
  CHECK (length(message_id) <= 998),
  CHECK (raw_bytes >= 0 AND raw_bytes <= 20971520),
  CHECK (length(CAST(raw_secret AS BLOB)) <= 16777216),
  CHECK (length(review_reason) <= 2000),
  CHECK (status IN ('ready', 'duplicate', 'invalid', 'pending', 'importing', 'imported', 'unknown', 'failed', 'skipped', 'canceled')),
  CHECK (length(subject) <= 1000)
);

CREATE TABLE IF NOT EXISTS "mailbox_import_jobs" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "request_key" TEXT NOT NULL,
  "format" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "folder" TEXT NOT NULL,
  "uid_validity" INTEGER NOT NULL,
  "source_digest" TEXT NOT NULL,
  "preview_digest" TEXT NOT NULL,
  "duplicate_policy" TEXT NOT NULL,
  "source_bytes" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'preview',
  "version" INTEGER NOT NULL DEFAULT 1,
  "preview_expires_at" INTEGER NOT NULL DEFAULT ((CAST(strftime('%s','now') AS INTEGER)*1000000) + 900*1000000),
  "payload_expires_at" INTEGER NOT NULL DEFAULT ((CAST(strftime('%s','now') AS INTEGER)*1000000) + 86400*1000000),
  "confirmed_at" INTEGER,
  "cancel_requested" INTEGER NOT NULL DEFAULT 0,
  "lease_token" TEXT NOT NULL DEFAULT '',
  "lease_until" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, id),
  UNIQUE (tenant_id, mailbox_id, request_key),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (duplicate_policy IN ('skip', 'keep_both')),
  CHECK (length(filename) >= 1 AND length(filename) <= 255),
  CHECK (length(folder) >= 1 AND length(folder) <= 1024),
  CHECK (format IN ('eml', 'mbox')),
  CHECK (length(preview_digest) = 64),
  CHECK (length(request_key) >= 8 AND length(request_key) <= 200),
  CHECK (source_bytes >= 1 AND source_bytes <= 20971520),
  CHECK (length(source_digest) = 64),
  CHECK (status IN ('preview', 'confirmed', 'running', 'partial', 'completed', 'canceled', 'uncertain', 'held')),
  CHECK (uid_validity >= 1 AND uid_validity <= 4294967295),
  CHECK (version > 0)
);

CREATE TABLE IF NOT EXISTS "mailbox_jobs" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "idempotency_key" TEXT NOT NULL,
  "payload" TEXT NOT NULL DEFAULT '[]',
  "status" TEXT NOT NULL DEFAULT 'pending',
  "claim_token" INTEGER NOT NULL DEFAULT 0,
  "lease_until" INTEGER,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "last_error" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, kind, idempotency_key),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (attempts >= 0),
  CHECK (length(idempotency_key) >= 1 AND length(idempotency_key) <= 200),
  CHECK (length(kind) >= 1 AND length(kind) <= 64),
  CHECK (status IN ('pending', 'leased', 'done', 'failed', 'uncertain'))
);

CREATE TABLE IF NOT EXISTS "mailbox_operation_tickets" (
  "token_hash" TEXT NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "session_hash" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "folder" TEXT NOT NULL DEFAULT '',
  "message_uid" INTEGER NOT NULL DEFAULT 0,
  "uid_validity" INTEGER NOT NULL DEFAULT 0,
  "expires_at" INTEGER NOT NULL,
  "consumed_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "kind" TEXT NOT NULL DEFAULT 'operation',
  PRIMARY KEY ("token_hash"),
  FOREIGN KEY (tenant_id, mailbox_id, session_hash) REFERENCES mailbox_sessions(tenant_id, mailbox_id, token_hash),
  CHECK (kind IN ('operation', 'sieve_bridge')),
  CHECK (message_uid >= 0 AND message_uid <= 4294967295),
  CHECK (scope IN ('ai_context', 'sieve')),
  CHECK (uid_validity >= 0 AND uid_validity <= 4294967295)
);

CREATE TABLE IF NOT EXISTS "mailbox_scheduled_sends" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "draft_folder" TEXT NOT NULL,
  "draft_uid" INTEGER NOT NULL,
  "send_at" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "last_error" TEXT,
  "smtp_secret" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "draft_uidvalidity" INTEGER NOT NULL DEFAULT 0,
  "idempotency_key" TEXT NOT NULL DEFAULT '',
  "request_hash" TEXT NOT NULL DEFAULT '',
  "claim_token" INTEGER NOT NULL DEFAULT 0,
  "lease_until" INTEGER,
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "sent_at" INTEGER,
  "sent_raw" BLOB,
  "sent_copy_state" TEXT NOT NULL DEFAULT 'none',
  "sent_raw_secret" TEXT NOT NULL DEFAULT '',
  "copy_pending_since" INTEGER,
  "copy_attempts" INTEGER NOT NULL DEFAULT 0,
  "smtp_password_version" TEXT NOT NULL DEFAULT '',
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (attempts >= 0),
  CHECK (length(draft_folder) >= 1 AND length(draft_folder) <= 1024),
  CHECK (draft_uid >= 1 AND draft_uid <= 4294967295),
  CHECK (draft_uidvalidity >= 0 AND draft_uidvalidity <= 4294967295),
  CHECK (sent_copy_state IN ('none', 'pending', 'unknown', 'complete', 'held')),
  CHECK (status IN ('pending', 'preparing', 'submitting', 'sent', 'uncertain', 'failed', 'cancelled', 'held')),
  CHECK (sent_raw IS NULL OR length(CAST(sent_raw AS BLOB)) >= 1 AND length(CAST(sent_raw AS BLOB)) <= 33554432)
);

CREATE TABLE IF NOT EXISTS "mailbox_send_receipts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "request_key" TEXT NOT NULL,
  "request_hash" TEXT NOT NULL,
  "message_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'prepared',
  "sent_copy_state" TEXT NOT NULL DEFAULT 'none',
  "raw_secret" TEXT NOT NULL,
  "smtp_secret" TEXT NOT NULL DEFAULT '',
  "smtp_password_version" TEXT NOT NULL DEFAULT '',
  "draft_folder" TEXT NOT NULL DEFAULT '',
  "draft_uid" INTEGER NOT NULL DEFAULT 0,
  "draft_uidvalidity" INTEGER NOT NULL DEFAULT 0,
  "draft_released" INTEGER NOT NULL DEFAULT 0,
  "claim_token" INTEGER NOT NULL DEFAULT 0,
  "lease_until" INTEGER,
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "copy_attempts" INTEGER NOT NULL DEFAULT 0,
  "copy_pending_since" INTEGER,
  "accepted_at" INTEGER,
  "last_error" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, request_key),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (draft_uid >= 0 AND draft_uid <= 4294967295),
  CHECK (draft_uidvalidity >= 0 AND draft_uidvalidity <= 4294967295),
  CHECK (length(message_id) >= 3 AND length(message_id) <= 998),
  CHECK (length(CAST(raw_secret AS BLOB)) <= 33554432),
  CHECK (length(request_hash) = 64),
  CHECK (length(request_key) >= 16 AND length(request_key) <= 128),
  CHECK (sent_copy_state IN ('none', 'pending', 'unknown', 'complete', 'held')),
  CHECK (status IN ('prepared', 'submitting', 'accepted', 'rejected', 'uncertain'))
);

CREATE TABLE IF NOT EXISTS "mailbox_sessions" (
  "token_hash" TEXT NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "password_version" TEXT NOT NULL,
  "expires_at" INTEGER NOT NULL,
  "revoked_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "origin_host" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("token_hash"),
  UNIQUE (tenant_id, mailbox_id, token_hash),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id)
);

CREATE TABLE IF NOT EXISTS "mailbox_settings" (
  "mailbox_id" INTEGER NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "version" INTEGER NOT NULL DEFAULT 1,
  "display_name" TEXT NOT NULL DEFAULT '',
  "signature_text" TEXT NOT NULL DEFAULT '',
  "signature_html" TEXT NOT NULL DEFAULT '',
  "preferences" TEXT NOT NULL DEFAULT '[]',
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "identity_profiles" TEXT NOT NULL DEFAULT '[]',
  PRIMARY KEY ("mailbox_id"),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(display_name) <= 128),
  CHECK (json_type(identity_profiles) = 'object'AND length(CAST(identity_profiles AS BLOB)) <= 65536),
  CHECK (length(CAST(preferences AS BLOB)) <= 8192),
  CHECK (length(signature_html) <= 16384),
  CHECK (length(signature_text) <= 8192),
  CHECK (version >= 1 AND version <= 2147483647)
);

CREATE TABLE IF NOT EXISTS "mailbox_snippets" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "title" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "shortcut" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, id),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(content) <= 32768),
  CHECK (length(shortcut) <= 64),
  CHECK (length(trim(title)) >= 1 AND length(trim(title)) <= 120)
);

CREATE TABLE IF NOT EXISTS "mailbox_spam_feedback" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "message_id" TEXT NOT NULL,
  "folder" TEXT NOT NULL,
  "verdict" TEXT NOT NULL,
  "sender_address" TEXT NOT NULL DEFAULT '',
  "sender_domain" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(folder) >= 1 AND length(folder) <= 1024),
  CHECK (length(message_id) >= 1 AND length(message_id) <= 998 AND instr(message_id, ' ') = 0 AND instr(message_id, ' ') = 0),
  CHECK (length(sender_address) <= 254),
  CHECK (length(sender_domain) <= 254),
  CHECK (verdict IN ('spam', 'ham'))
);

CREATE TABLE IF NOT EXISTS "mailbox_spam_senders" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL DEFAULT 0,
  "scope" TEXT NOT NULL,
  "address" TEXT NOT NULL DEFAULT '',
  "domain" TEXT NOT NULL DEFAULT '',
  "list" TEXT NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "mailbox_id", "address", "domain", "list"),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(address) <= 254),
  CHECK (scope = 'mailbox'AND mailbox_id > 0 OR scope = 'tenant'AND mailbox_id = 0),
  CHECK (address <> ''OR domain <> ''),
  CHECK (length(domain) <= 254),
  CHECK (list IN ('allow', 'deny')),
  CHECK (scope IN ('mailbox', 'tenant'))
);

CREATE TABLE IF NOT EXISTS "mailbox_spam_tokens" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "token" TEXT NOT NULL,
  "spam_count" INTEGER NOT NULL DEFAULT 0,
  "ham_count" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "mailbox_id", "token"),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE CASCADE,
  CHECK (ham_count >= 0 AND ham_count <= 1000000000),
  CHECK (spam_count >= 0 AND spam_count <= 1000000000),
  CHECK (length(token) >= 1 AND length(token) <= 64)
);

CREATE TABLE IF NOT EXISTS "mailbox_storage_reservations" (
  "address" TEXT NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  PRIMARY KEY ("address"),
  UNIQUE (mailbox_id)
);

CREATE TABLE IF NOT EXISTS "mailbox_sync_cursors" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "protocol" TEXT NOT NULL,
  "client_key" TEXT NOT NULL,
  "cursor_id" INTEGER NOT NULL DEFAULT 0,
  "epoch" INTEGER NOT NULL DEFAULT 1,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, mailbox_id, protocol, client_key),
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id),
  CHECK (length(client_key) >= 1 AND length(client_key) <= 200),
  CHECK (cursor_id >= 0),
  CHECK (epoch >= 1),
  CHECK (protocol IN ('web', 'carddav', 'caldav', 'eas'))
);

CREATE TABLE IF NOT EXISTS "mailbox_usage" (
  "mailbox_id" INTEGER NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "day" TEXT NOT NULL,
  "bytes_used" INTEGER NOT NULL DEFAULT 0,
  "messages_sent" INTEGER NOT NULL DEFAULT 0,
  "messages_recv" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("mailbox_id", "day"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (mailbox_id, tenant_id) REFERENCES mailboxes(id, tenant_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "mailboxes" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "local_part" TEXT NOT NULL,
  "address" TEXT NOT NULL,
  "display_name" TEXT,
  "password_hash" TEXT NOT NULL,
  "quota_bytes" INTEGER NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'active',
  "send_enabled" INTEGER NOT NULL DEFAULT 1,
  "sieve_script" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "bytes_used" INTEGER NOT NULL DEFAULT 0,
  "usage_measured_at" INTEGER,
  "usage_error" TEXT,
  "password_version" INTEGER NOT NULL DEFAULT 0,
  "password_revoke_pending" INTEGER NOT NULL DEFAULT 0,
  "sieve_mode" TEXT NOT NULL DEFAULT 'managed',
  UNIQUE (address),
  UNIQUE (domain_id, local_part),
  UNIQUE (id, tenant_id),
  FOREIGN KEY (domain_id, tenant_id) REFERENCES domains(id, tenant_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (bytes_used >= 0),
  CHECK (password_version >= 0),
  CHECK (quota_bytes >= -1),
  CHECK (sieve_mode IN ('managed', 'legacy_v80')),
  CHECK (status IN ('active', 'disabled', 'locked', 'deleted'))
);

CREATE TABLE IF NOT EXISTS "managed_dns_zones" (
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER NOT NULL,
  "records" TEXT NOT NULL,
  "plan_id" TEXT NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("domain_id"),
  FOREIGN KEY (tenant_id, domain_id) REFERENCES domains(tenant_id, id),
  FOREIGN KEY (tenant_id, plan_id) REFERENCES dns_change_plans(tenant_id, id)
);

CREATE TABLE IF NOT EXISTS "marketing_campaign_stats" (
  "tenant_id" INTEGER NOT NULL,
  "campaign_id" INTEGER NOT NULL,
  "sent" INTEGER NOT NULL DEFAULT 0,
  "failed" INTEGER NOT NULL DEFAULT 0,
  "uncertain" INTEGER NOT NULL DEFAULT 0,
  "unsubscribed" INTEGER NOT NULL DEFAULT 0,
  "bounced" INTEGER NOT NULL DEFAULT 0,
  "bounced_unknown" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "campaign_id"),
  FOREIGN KEY (tenant_id, campaign_id) REFERENCES marketing_campaigns(tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (bounced >= 0),
  CHECK (bounced_unknown >= 0),
  CHECK (failed >= 0),
  CHECK (sent >= 0),
  CHECK (uncertain >= 0),
  CHECK (unsubscribed >= 0)
);

CREATE TABLE IF NOT EXISTS "marketing_campaigns" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "channel_id" INTEGER NOT NULL,
  "template_id" INTEGER NOT NULL,
  "list_id" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "subject_snapshot" TEXT,
  "body_snapshot" TEXT,
  "scheduled_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, channel_id) REFERENCES marketing_channels(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  FOREIGN KEY (tenant_id, list_id) REFERENCES marketing_lists(tenant_id, id),
  FOREIGN KEY (tenant_id, template_id) REFERENCES marketing_templates(tenant_id, id),
  CHECK (length(name) >= 1 AND length(name) <= 200),
  CHECK (status IN ('draft', 'scheduled', 'running', 'paused', 'canceled', 'completed'))
);

CREATE TABLE IF NOT EXISTS "marketing_channels" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "sender_address" TEXT NOT NULL,
  "encrypted_config" TEXT NOT NULL,
  "enabled" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (kind IN ('dedicated_gateway', 'dedicated_ip')),
  CHECK (length(name) >= 1 AND length(name) <= 200)
);

CREATE TABLE IF NOT EXISTS "marketing_contacts" (
  "tenant_id" INTEGER NOT NULL,
  "list_id" INTEGER NOT NULL,
  "email" TEXT NOT NULL,
  "consent_source" TEXT NOT NULL,
  "opted_in" INTEGER NOT NULL DEFAULT 1,
  "consent_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id", "list_id", "email"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  FOREIGN KEY (tenant_id, list_id) REFERENCES marketing_lists(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(consent_source) >= 1 AND length(consent_source) <= 256)
);

CREATE TABLE IF NOT EXISTS "marketing_feedback" (
  "channel_id" INTEGER NOT NULL,
  "event_id" TEXT NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "recipient_id" INTEGER NOT NULL,
  "status" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("channel_id", "event_id"),
  FOREIGN KEY (channel_id) REFERENCES marketing_channels(id),
  FOREIGN KEY (tenant_id, recipient_id) REFERENCES marketing_recipients(tenant_id, id)
);

CREATE TABLE IF NOT EXISTS "marketing_flow_content_snapshots" (
  "tenant_id" INTEGER NOT NULL,
  "runtime_flow_id" INTEGER NOT NULL,
  "step_key" TEXT NOT NULL,
  "template_id" INTEGER NOT NULL,
  "subject" TEXT NOT NULL,
  "text_body" TEXT NOT NULL,
  PRIMARY KEY ("tenant_id", "runtime_flow_id", "step_key"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, runtime_flow_id) REFERENCES marketing_flows(tenant_id, id)
);

CREATE TABLE IF NOT EXISTS "marketing_flow_definitions" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "draft" TEXT NOT NULL,
  "draft_revision" INTEGER NOT NULL DEFAULT 1,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "published_version" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (json_type(draft) = 'object'),
  CHECK (draft_revision > 0),
  CHECK (length(name) >= 1 AND length(name) <= 200),
  CHECK (published_version >= 0),
  CHECK (status IN ('draft', 'active', 'paused'))
);

CREATE TABLE IF NOT EXISTS "marketing_flow_entries" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "definition_id" INTEGER NOT NULL,
  "version_id" INTEGER NOT NULL,
  "event_key" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "list_id" INTEGER NOT NULL,
  "recipient_count" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, definition_id, event_key),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, definition_id, version_id) REFERENCES marketing_flow_versions(tenant_id, definition_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, list_id) REFERENCES marketing_lists(tenant_id, id),
  CHECK (length(event_key) >= 8 AND length(event_key) <= 128),
  CHECK (recipient_count >= 0 AND recipient_count <= 1000),
  CHECK (source = 'contact_enrolled')
);

CREATE TABLE IF NOT EXISTS "marketing_flow_node_executions" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "position_id" INTEGER NOT NULL,
  "lease_fence" INTEGER NOT NULL,
  "node_key" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "error_code" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, position_id, lease_fence),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, position_id) REFERENCES marketing_flow_positions(tenant_id, id),
  CHECK (length(error_code) <= 100),
  CHECK (status IN ('submitted', 'advanced', 'waiting', 'blocked', 'failed', 'uncertain'))
);

CREATE TABLE IF NOT EXISTS "marketing_flow_positions" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "flow_id" INTEGER NOT NULL,
  "email" TEXT NOT NULL,
  "step_key" TEXT NOT NULL,
  "unsubscribed" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "wait_until" INTEGER,
  "delivery_uncertain" INTEGER NOT NULL DEFAULT 0,
  "lease_owner" TEXT,
  "lease_until" INTEGER,
  "lease_fence" INTEGER NOT NULL DEFAULT 0,
  "entry_id" INTEGER,
  "event_facts" TEXT NOT NULL DEFAULT '[]',
  "last_error" TEXT NOT NULL DEFAULT '',
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "attempt_count" INTEGER NOT NULL DEFAULT 0,
  "stopped_at" INTEGER,
  "flow_window_id" INTEGER,
  "flow_reserved" INTEGER NOT NULL DEFAULT 0,
  UNIQUE (tenant_id, flow_id, email),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, entry_id) REFERENCES marketing_flow_entries(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, flow_id) REFERENCES marketing_flows(tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, flow_window_id) REFERENCES marketing_quota_windows(tenant_id, id),
  CHECK (attempt_count >= 0),
  CHECK (instr(email, '@') > 1),
  CHECK (json_type(event_facts) = 'object'),
  CHECK (length(last_error) <= 100)
);

CREATE TABLE IF NOT EXISTS "marketing_flow_steps" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "flow_id" INTEGER NOT NULL,
  "step_key" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "next_key" TEXT NOT NULL DEFAULT '',
  "opened_key" TEXT NOT NULL DEFAULT '',
  "unsubscribed_key" TEXT NOT NULL DEFAULT '',
  "position" INTEGER NOT NULL,
  "wait_seconds" INTEGER NOT NULL DEFAULT 0,
  "condition_field" TEXT NOT NULL DEFAULT '',
  "condition_operator" TEXT NOT NULL DEFAULT '',
  "condition_value" TEXT NOT NULL DEFAULT '',
  UNIQUE (tenant_id, flow_id, step_key),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, flow_id) REFERENCES marketing_flows(tenant_id, id) ON DELETE CASCADE,
  CHECK (kind IN ('send', 'wait', 'condition', 'stop')),
  CHECK ("position" >= 0 AND "position" <= 19),
  CHECK (length(step_key) >= 1 AND length(step_key) <= 40),
  CHECK (wait_seconds >= 0 AND wait_seconds <= 2592000)
);

CREATE TABLE IF NOT EXISTS "marketing_flow_versions" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "definition_id" INTEGER NOT NULL,
  "version" INTEGER NOT NULL,
  "draft_revision" INTEGER NOT NULL,
  "runtime_flow_id" INTEGER NOT NULL,
  "definition" TEXT NOT NULL,
  "published_by" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, definition_id, draft_revision),
  UNIQUE (tenant_id, definition_id, id),
  UNIQUE (tenant_id, definition_id, version),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, runtime_flow_id),
  FOREIGN KEY (published_by) REFERENCES users(id),
  FOREIGN KEY (tenant_id, definition_id) REFERENCES marketing_flow_definitions(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, runtime_flow_id) REFERENCES marketing_flows(tenant_id, id),
  CHECK (json_type(definition) = 'object'),
  CHECK (version > 0)
);

CREATE TABLE IF NOT EXISTS "marketing_flows" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (length(name) >= 1 AND length(name) <= 200),
  CHECK (status IN ('draft', 'active', 'paused'))
);

CREATE TABLE IF NOT EXISTS "marketing_lists" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (length(name) >= 1 AND length(name) <= 200)
);

CREATE TABLE IF NOT EXISTS "marketing_quota_windows" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "starts_at" INTEGER NOT NULL,
  "ends_at" INTEGER NOT NULL,
  "timezone" TEXT NOT NULL,
  "used_count" INTEGER NOT NULL DEFAULT 0,
  "next_send_at" INTEGER NOT NULL DEFAULT -9223372036854775808,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, starts_at),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (ends_at > starts_at),
  CHECK (used_count >= 0)
);

CREATE TABLE IF NOT EXISTS "marketing_recipients" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "campaign_id" INTEGER NOT NULL,
  "email" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "lease_owner" TEXT,
  "lease_until" INTEGER,
  "fence" INTEGER NOT NULL DEFAULT 0,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "window_id" INTEGER,
  "reserved" INTEGER NOT NULL DEFAULT 0,
  "result_code" TEXT,
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "completed_at" INTEGER,
  "resolution_reason" TEXT,
  UNIQUE (campaign_id, email),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, campaign_id) REFERENCES marketing_campaigns(tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  FOREIGN KEY (tenant_id, window_id) REFERENCES marketing_quota_windows(tenant_id, id),
  CHECK (attempts >= 0),
  CHECK (status IN ('queued', 'leased', 'submitting', 'sent', 'uncertain', 'failed', 'suppressed', 'canceled', 'bounced'))
);

CREATE TABLE IF NOT EXISTS "marketing_suppressions" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "email" TEXT NOT NULL,
  "reason" TEXT NOT NULL DEFAULT 'manual',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (email = lower(trim(email)) AND email <> ''),
  CHECK (reason IN ('unsubscribe', 'bounce', 'complaint', 'manual'))
);

CREATE TABLE IF NOT EXISTS "marketing_templates" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "text_body" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (length(name) >= 1 AND length(name) <= 200),
  CHECK (length(CAST(text_body AS BLOB)) <= 1048576)
);

CREATE TABLE IF NOT EXISTS "notification_outbox" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER,
  "user_id" INTEGER,
  "kind" TEXT NOT NULL,
  "message_key" TEXT NOT NULL,
  "params" TEXT NOT NULL DEFAULT '[]',
  "dedupe_key" TEXT NOT NULL,
  "channel" TEXT NOT NULL,
  "state" TEXT NOT NULL DEFAULT 'pending',
  "recipient" TEXT,
  "recipient_verified" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "read_at" INTEGER,
  "delivered_at" INTEGER,
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "lease_until" INTEGER,
  "fence" INTEGER NOT NULL DEFAULT 0,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "secret_payload" TEXT,
  "last_error" TEXT,
  UNIQUE (dedupe_key),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  FOREIGN KEY (user_id) REFERENCES users(id),
  CHECK (channel IN ('in_app', 'email')),
  CHECK (channel <> 'email'OR recipient IS NOT NULL AND (recipient_verified OR kind = 'contact_verification')),
  CHECK (state IN ('pending', 'delivered', 'uncertain', 'failed', 'blocked'))
);

CREATE TABLE IF NOT EXISTS "onboarding_tasks" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "domain_id" INTEGER,
  "order_id" INTEGER,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "step" TEXT NOT NULL DEFAULT 'domain_verification',
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "max_attempts" INTEGER NOT NULL DEFAULT 5,
  "last_error" TEXT,
  "leased_until" INTEGER,
  "leased_by" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "completed_at" INTEGER,
  "fence" INTEGER NOT NULL DEFAULT 0,
  "next_attempt_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "desired_generation" TEXT,
  "last_error_code" TEXT,
  FOREIGN KEY (domain_id) REFERENCES domains(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (attempts >= 0 AND max_attempts > 0 AND attempts <= max_attempts),
  CHECK (status IN ('pending', 'running', 'completed', 'failed', 'blocked')),
  CHECK (step IN ('domain_verification', 'bootstrap_config', 'dns_propagation', 'certificate_issue', 'mailbox_provision', 'configuration_apply', 'protocol_readiness', 'ready'))
);

CREATE TABLE IF NOT EXISTS "operational_alerts" (
  "alert_key" TEXT NOT NULL,
  "tenant_id" INTEGER,
  "kind" TEXT NOT NULL,
  "state" TEXT NOT NULL,
  "first_seen_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "last_seen_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "resolved_at" INTEGER,
  PRIMARY KEY ("alert_key"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (state IN ('firing', 'resolved'))
);

CREATE TABLE IF NOT EXISTS "platform_admins" (
  "user_id" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("user_id"),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "platform_marketing_dispatch" (
  "tenant_id" INTEGER NOT NULL,
  "last_turn" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("tenant_id"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (last_turn >= 0)
);

CREATE TABLE IF NOT EXISTS "recall_requests" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "message_id" TEXT NOT NULL,
  "requested_by" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "reason" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "archive_entry_id" INTEGER,
  "mailbox_id" INTEGER,
  "completed_at" INTEGER,
  "preview_actor_id" INTEGER,
  "preview_token" TEXT,
  "preview_digest" TEXT,
  "preview_snapshot" BLOB,
  "preview_expires_at" INTEGER,
  "confirmed_at" INTEGER,
  "selected_copy_keys" TEXT NOT NULL DEFAULT '[]',
  "attempt_epoch" INTEGER NOT NULL DEFAULT 0,
  "local_result" TEXT NOT NULL DEFAULT '{"items": []}',
  "result_history" TEXT NOT NULL DEFAULT '[]',
  UNIQUE (tenant_id, archive_entry_id),
  FOREIGN KEY (archive_entry_id, tenant_id) REFERENCES archive_entries(id, tenant_id) ON DELETE RESTRICT,
  FOREIGN KEY (tenant_id, mailbox_id) REFERENCES mailboxes(tenant_id, id) ON DELETE RESTRICT,
  FOREIGN KEY (preview_actor_id) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (attempt_epoch >= 0),
  CHECK (json_type(local_result) = 'object'),
  CHECK (preview_snapshot IS NULL OR length(CAST(preview_snapshot AS BLOB)) <= 262144),
  CHECK (json_type(result_history) = 'array'AND json_array_length(result_history) <= 100),
  CHECK (json_type(selected_copy_keys) = 'array'AND json_array_length(selected_copy_keys) <= 100),
  CHECK (status IN ('preview', 'pending', 'delivered', 'failed', 'expired', 'local_recalled', 'uncertain'))
);

CREATE TABLE IF NOT EXISTS "restore_quarantine" (
  "singleton" INTEGER NOT NULL DEFAULT 1,
  "active" INTEGER NOT NULL,
  "reason" TEXT NOT NULL,
  "started_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("singleton"),
  CHECK (reason = 'restore'),
  CHECK (singleton)
);

CREATE TABLE IF NOT EXISTS "retention_policies" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "retention_days" INTEGER NOT NULL,
  "action" TEXT NOT NULL DEFAULT 'soft_delete',
  "active" INTEGER NOT NULL DEFAULT 0,
  "created_by" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "confirmed_preview" TEXT,
  "authorization_grant_id" INTEGER,
  FOREIGN KEY (tenant_id, authorization_grant_id) REFERENCES compliance_grants(tenant_id, id),
  FOREIGN KEY (confirmed_preview) REFERENCES retention_previews(id),
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (action IN ('soft_delete', 'hard_delete', 'archive_export')),
  CHECK (retention_days > 0)
);

CREATE TABLE IF NOT EXISTS "retention_previews" (
  "id" TEXT NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "retention_days" INTEGER NOT NULL,
  "candidate_count" INTEGER NOT NULL,
  "candidate_digest" TEXT NOT NULL,
  "created_by" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "expires_at" INTEGER NOT NULL DEFAULT ((CAST(strftime('%s','now') AS INTEGER)*1000000) + 900*1000000),
  "confirmed_at" INTEGER,
  "authorization_grant_id" INTEGER,
  PRIMARY KEY ("id"),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, authorization_grant_id) REFERENCES compliance_grants(tenant_id, id),
  FOREIGN KEY (created_by) REFERENCES users(id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id),
  CHECK (retention_days > 0)
);

CREATE TABLE IF NOT EXISTS "roundcube_bridge_requests" (
  "nonce" TEXT NOT NULL,
  "expires_at" INTEGER NOT NULL,
  PRIMARY KEY ("nonce"),
  CHECK (length(nonce) >= 32 AND length(nonce) <= 128)
);

CREATE TABLE IF NOT EXISTS "sessions" (
  "id" TEXT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "tenant_id" INTEGER,
  "csrf_token" TEXT NOT NULL,
  "user_agent" TEXT,
  "ip" TEXT,
  "expires_at" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "mfa_verified_at" INTEGER,
  "kind" TEXT NOT NULL DEFAULT 'panel',
  "credential_version" INTEGER NOT NULL DEFAULT 0,
  "origin_host" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CHECK (credential_version >= 0),
  CHECK (kind IN ('panel', 'legacy'))
);

CREATE TABLE IF NOT EXISTS "settings" (
  "scope" TEXT NOT NULL,
  "scope_id" INTEGER NOT NULL DEFAULT 0,
  "key" TEXT NOT NULL,
  "value" TEXT NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("scope", "scope_id", "key"),
  CHECK (scope IN ('platform', 'brand', 'tenant'))
);

CREATE TABLE IF NOT EXISTS "tenant_directory_contacts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "display_name" TEXT NOT NULL DEFAULT '',
  "given_name" TEXT NOT NULL DEFAULT '',
  "family_name" TEXT NOT NULL DEFAULT '',
  "organization" TEXT NOT NULL DEFAULT '',
  "department" TEXT NOT NULL DEFAULT '',
  "job_title" TEXT NOT NULL DEFAULT '',
  "emails" TEXT NOT NULL DEFAULT '[]',
  "phones" TEXT NOT NULL DEFAULT '[]',
  "addresses" TEXT NOT NULL DEFAULT '[]',
  "note" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (length(department) <= 200),
  CHECK (length(display_name) <= 200),
  CHECK (length(family_name) <= 100),
  CHECK (length(given_name) <= 100),
  CHECK (length(job_title) <= 200),
  CHECK (length(note) <= 4000),
  CHECK (length(organization) <= 200)
);

CREATE TABLE IF NOT EXISTS "tenant_directory_settings" (
  "tenant_id" INTEGER NOT NULL,
  "enabled" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  PRIMARY KEY ("tenant_id"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "tenants" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "brand_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "owner_user_id" INTEGER,
  "settings" TEXT NOT NULL DEFAULT '[]',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (brand_id, slug),
  FOREIGN KEY (brand_id) REFERENCES brands(id) ON DELETE RESTRICT,
  FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CHECK (status IN ('pending', 'active', 'suspended', 'closed'))
);

CREATE TABLE IF NOT EXISTS "ticket_attachments" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "message_id" INTEGER NOT NULL,
  "filename" TEXT NOT NULL,
  "content_type" TEXT NOT NULL,
  "content" BLOB NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  FOREIGN KEY (tenant_id, message_id) REFERENCES ticket_messages(tenant_id, id) ON DELETE CASCADE,
  CHECK (length(CAST(content AS BLOB)) >= 1 AND length(CAST(content AS BLOB)) <= 2097152),
  CHECK (content_type IN ('text/plain', 'image/png', 'image/jpeg', 'application/pdf'))
);

CREATE TABLE IF NOT EXISTS "ticket_messages" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "ticket_id" INTEGER NOT NULL,
  "author_id" INTEGER NOT NULL,
  "body" TEXT NOT NULL,
  "is_staff" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "tenant_id" INTEGER NOT NULL,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, ticket_id) REFERENCES tickets(tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,
  CHECK (length(CAST(body AS BLOB)) >= 1 AND length(CAST(body AS BLOB)) <= 65536)
);

CREATE TABLE IF NOT EXISTS "tickets" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "opened_by" INTEGER NOT NULL,
  "subject" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open',
  "priority" TEXT NOT NULL DEFAULT 'normal',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "assigned_to" INTEGER,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (assigned_to) REFERENCES users(id),
  FOREIGN KEY (opened_by) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  CHECK (priority IN ('low', 'normal', 'high')),
  CHECK (status IN ('open', 'pending', 'resolved', 'closed')),
  CHECK (length(subject) >= 1 AND length(subject) <= 200)
);

CREATE TABLE IF NOT EXISTS "user_tenant_roles" (
  "user_id" INTEGER NOT NULL,
  "tenant_id" INTEGER NOT NULL,
  "role" TEXT NOT NULL,
  PRIMARY KEY ("user_id", "tenant_id"),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CHECK (role IN ('owner', 'admin', 'billing', 'member'))
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "email" TEXT NOT NULL,
  "password_hash" TEXT NOT NULL,
  "display_name" TEXT,
  "locale" TEXT NOT NULL DEFAULT 'zh-CN',
  "timezone" TEXT NOT NULL DEFAULT 'Asia/Shanghai',
  "status" TEXT NOT NULL DEFAULT 'active',
  "mfa_secret" TEXT,
  "mfa_enabled" INTEGER NOT NULL DEFAULT 0,
  "password_changed_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000000),
  "mfa_recovery_codes" TEXT NOT NULL DEFAULT '[]',
  "credential_version" INTEGER NOT NULL DEFAULT 0,
  UNIQUE (email),
  CHECK (credential_version >= 0),
  CHECK (status IN ('active', 'disabled', 'locked'))
);

-- Webmail v1 新表（v3.2 §8.2；QA S0-b 后口径：三表补 mailbox_id）
-- scheduled_sends 不新建表：mailbox_scheduled_sends（0076）扩列接调度器家族。

-- 迁移簿记表（106 表门之一；user_version 是迁移链的权威，
-- schema_migrations 仅为工具面 parity：version=已应用版本、dirty=事务标记）。
CREATE TABLE IF NOT EXISTS "schema_migrations" (
  "version" INTEGER PRIMARY KEY,
  "dirty" INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "snoozes" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "folder" TEXT NOT NULL,
  "uid" INTEGER NOT NULL,
  "uid_validity" INTEGER NOT NULL,
  "snooze_until" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "created_at" INTEGER NOT NULL,
  "updated_at" INTEGER NOT NULL,
  UNIQUE ("mailbox_id", "uid_validity", "uid"),
  FOREIGN KEY ("tenant_id", "mailbox_id") REFERENCES "mailboxes"("tenant_id", "id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "labels" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "color_idx" INTEGER NOT NULL,
  "sort" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL,
  "updated_at" INTEGER NOT NULL,
  UNIQUE ("mailbox_id", "name"),
  FOREIGN KEY ("tenant_id", "mailbox_id") REFERENCES "mailboxes"("tenant_id", "id") ON DELETE CASCADE
);

-- 复合身份（v3.2 §8.1 条款）：无单一稳定 message 主键（maildir 无跨 MOVE
-- 对象 ID），以 (mailbox, folder, uid_validity, uid) 为行身份 + fingerprint
-- 用于外部 MOVE 后的对账恢复。
CREATE TABLE IF NOT EXISTS "message_labels" (
  "tenant_id" INTEGER NOT NULL,
  "mailbox_id" INTEGER NOT NULL,
  "folder" TEXT NOT NULL,
  "uid_validity" INTEGER NOT NULL,
  "uid" INTEGER NOT NULL,
  "label_id" INTEGER NOT NULL,
  "fingerprint" TEXT NOT NULL DEFAULT '',
  "orphan_since" INTEGER,
  PRIMARY KEY ("mailbox_id", "folder", "uid_validity", "uid", "label_id"),
  FOREIGN KEY ("label_id") REFERENCES "labels"("id") ON DELETE CASCADE
);

-- mailbox_scheduled_sends 接入 agent 调度器家族的扩列（0076 原复合键
-- (tenant,mailbox,folder,draft_uid,draft_uidvalidity) 不动，见 v3.2 §8.2）。
ALTER TABLE "mailbox_scheduled_sends" ADD COLUMN "scheduled_at" INTEGER;
ALTER TABLE "mailbox_scheduled_sends" ADD COLUMN "slot_tz" TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE "mailbox_scheduled_sends" ADD COLUMN "retry_count" INTEGER NOT NULL DEFAULT 0;

-- QA S1-Fail P1：新表外键（缺失即跨邮箱/跨标签孤儿行）。
-- mailboxes 的 (tenant_id,id) 在生成物中已有 UNIQUE（PG 约束平移）。

CREATE INDEX IF NOT EXISTS ai_usage_active_reservations_idx ON ai_usage_requests (tenant_id, mode) WHERE (status = 'reserved');
CREATE INDEX IF NOT EXISTS ai_usage_nonplatform_window_idx ON ai_usage_requests (tenant_id, created_at, mailbox_id) WHERE ((mode IN ('byo', 'local')) AND (status <> 'released'));
CREATE INDEX IF NOT EXISTS ai_usage_requests_tenant_id_period_start_status_idx ON ai_usage_requests (tenant_id, period_start, status);
CREATE UNIQUE INDEX IF NOT EXISTS ai_usage_requests_tenant_id_request_key_key ON ai_usage_requests (tenant_id, request_key);
CREATE UNIQUE INDEX IF NOT EXISTS api_tokens_prefix_key ON api_tokens (prefix);
CREATE UNIQUE INDEX IF NOT EXISTS application_credentials_token_hash_key ON application_credentials (token_hash);
CREATE INDEX IF NOT EXISTS application_credentials_user_id_idx ON application_credentials (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS archive_approval_requests_tenant_id_id_key ON archive_approval_requests (tenant_id, id);
CREATE INDEX IF NOT EXISTS archive_entries_tenant_id_received_at_idx ON archive_entries (tenant_id, received_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS archive_entries_tenant_mailbox_message_uniq ON archive_entries (tenant_id, mailbox_id, message_id, raw_sha256);
CREATE INDEX IF NOT EXISTS archive_entries_tenant_received_idx ON archive_entries (tenant_id, deleted_at, received_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS archive_id_tenant_unique ON archive_entries (id, tenant_id);
CREATE UNIQUE INDEX IF NOT EXISTS archive_investigation_sources_investigation_id_archive_entr_key ON archive_investigation_sources (investigation_id, archive_entry_id);
CREATE UNIQUE INDEX IF NOT EXISTS archive_case_request_key ON archive_investigations (tenant_id, created_by, request_key) WHERE (request_key <> '');
CREATE UNIQUE INDEX IF NOT EXISTS archive_investigations_tenant_id_id_key ON archive_investigations (tenant_id, id);
CREATE INDEX IF NOT EXISTS audit_logs_action_created_at_idx ON audit_logs (action, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_tenant_id_created_at_idx ON audit_logs (tenant_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS backup_runs_run_uid_key ON backup_runs (run_uid);
CREATE INDEX IF NOT EXISTS backup_runs_started_at_idx ON backup_runs (started_at DESC);
