-- Port of PG function domains_touch_updated_at (updated_at 自动触碰)
CREATE TRIGGER IF NOT EXISTS domains_touch_updated_at
AFTER UPDATE ON domains
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
  UPDATE domains SET updated_at = CAST(strftime('%s','now') AS INTEGER)*1000000 WHERE id = NEW.id;
END;

-- Port of PG function urmail_ai_configuration_consent_guard (版本自增、插入默认与 configuration_digest 已承接（前三者由触发器，digest 由 internal/store/sqlite_methods.go 的 refreshAIConfigurationDigest 在每条写入路径后重算）；consent 落库前的 role/actor 判定仍为会话语义)
CREATE TRIGGER IF NOT EXISTS ai_config_version_keep_or_bump
AFTER UPDATE ON ai_provider_configs
WHEN NEW.configuration_version IS NOT (CASE WHEN NEW.mode IS NOT OLD.mode OR NEW.provider IS NOT OLD.provider OR NEW.endpoint IS NOT OLD.endpoint OR NEW.model IS NOT OLD.model OR NEW.cloud_scope_hash IS NOT OLD.cloud_scope_hash THEN OLD.configuration_version + 1 ELSE OLD.configuration_version END)
BEGIN
  SELECT CASE WHEN OLD.configuration_version >= 9007199254740991 AND (NEW.mode IS NOT OLD.mode OR NEW.provider IS NOT OLD.provider OR NEW.endpoint IS NOT OLD.endpoint OR NEW.model IS NOT OLD.model OR NEW.cloud_scope_hash IS NOT OLD.cloud_scope_hash) THEN RAISE(ABORT,'AI_CONFIGURATION_VERSION_EXHAUSTED') END;
  UPDATE ai_provider_configs SET configuration_version = CASE WHEN NEW.mode IS NOT OLD.mode OR NEW.provider IS NOT OLD.provider OR NEW.endpoint IS NOT OLD.endpoint OR NEW.model IS NOT OLD.model OR NEW.cloud_scope_hash IS NOT OLD.cloud_scope_hash THEN OLD.configuration_version + 1 ELSE OLD.configuration_version END WHERE tenant_id = NEW.tenant_id;
END;

CREATE TRIGGER IF NOT EXISTS ai_config_insert_defaults
AFTER INSERT ON ai_provider_configs
WHEN NEW.configuration_version IS NOT 1 OR NEW.tenant_local_only IS NOT 1 OR NEW.cloud_consent_digest IS NOT '' OR NEW.cloud_consent_scope_hash IS NOT '' OR NEW.cloud_consent_by IS NOT NULL OR NEW.cloud_consent_at IS NOT NULL OR NEW.cloud_consent_revoked_at IS NOT NULL
BEGIN
  UPDATE ai_provider_configs SET configuration_version = 1, tenant_local_only = 1, cloud_consent_digest = '', cloud_consent_scope_hash = '', cloud_consent_by = NULL, cloud_consent_at = NULL, cloud_consent_revoked_at = NULL WHERE tenant_id = NEW.tenant_id;
END;

-- APP-PENDING (urmail_ai_configuration_consent_guard): AI_TENANT_CONSENT_REQUIRED / AI_CLOUD_CONSENT_STALE（BEFORE UPDATE 里对 consent 列变更的 role+actor 校验）→ S2 装饰器；urmail_app 角色下切到 local 时撤销同意由 Go 手写方法按“local 即撤销”的严格方向承接（SQLite 无会话角色）

-- Port of PG function urmail_alias_sender_logins_guard (sender_logins 为 TEXT(JSON 数组)；catchall 禁登录、路由变更清空（校验按清空后的有效值，等价 PG 先 NEW:='{}' 再校验）、逐登录校验归属与 JSON 合法性)
CREATE TRIGGER IF NOT EXISTS alias_sender_logins_catchall_guard_insert
BEFORE INSERT ON mailbox_aliases
WHEN NEW.kind = 'catchall' AND json_array_length(CASE WHEN json_valid(NEW.sender_logins) THEN NEW.sender_logins END) > 0
BEGIN
  SELECT RAISE(ABORT,'ALIAS_CATCHALL_SENDER_LOGIN_FORBIDDEN');
END;

CREATE TRIGGER IF NOT EXISTS alias_sender_logins_catchall_guard_update
BEFORE UPDATE ON mailbox_aliases
WHEN NEW.kind = 'catchall' AND json_array_length(CASE WHEN (NEW.target IS NOT OLD.target OR NEW.local_part IS NOT OLD.local_part OR NEW.kind IS NOT OLD.kind OR NEW.domain_id IS NOT OLD.domain_id) AND NEW.sender_logins IS OLD.sender_logins THEN '[]' WHEN json_valid(NEW.sender_logins) THEN NEW.sender_logins END) > 0
BEGIN
  SELECT RAISE(ABORT,'ALIAS_CATCHALL_SENDER_LOGIN_FORBIDDEN');
END;

CREATE TRIGGER IF NOT EXISTS alias_sender_logins_membership_guard_insert
BEFORE INSERT ON mailbox_aliases
WHEN NOT json_valid(NEW.sender_logins) OR EXISTS(SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.sender_logins) THEN NEW.sender_logins END) je WHERE lower(je.value) IS NOT je.value OR length(je.value) > 254 OR NOT EXISTS(SELECT 1 FROM mailboxes m WHERE m.tenant_id = NEW.tenant_id AND m.address = je.value AND m.status <> 'deleted'))
BEGIN
  SELECT RAISE(ABORT,'ALIAS_SENDER_LOGIN_NOT_TENANT_MAILBOX');
END;

CREATE TRIGGER IF NOT EXISTS alias_sender_logins_membership_guard_update
BEFORE UPDATE ON mailbox_aliases
WHEN NOT json_valid(NEW.sender_logins) OR EXISTS(SELECT 1 FROM json_each(CASE WHEN (NEW.target IS NOT OLD.target OR NEW.local_part IS NOT OLD.local_part OR NEW.kind IS NOT OLD.kind OR NEW.domain_id IS NOT OLD.domain_id) AND NEW.sender_logins IS OLD.sender_logins THEN '[]' WHEN json_valid(NEW.sender_logins) THEN NEW.sender_logins END) je WHERE lower(je.value) IS NOT je.value OR length(je.value) > 254 OR NOT EXISTS(SELECT 1 FROM mailboxes m WHERE m.tenant_id = NEW.tenant_id AND m.address = je.value AND m.status <> 'deleted'))
BEGIN
  SELECT RAISE(ABORT,'ALIAS_SENDER_LOGIN_NOT_TENANT_MAILBOX');
END;

CREATE TRIGGER IF NOT EXISTS alias_sender_logins_routing_reset
AFTER UPDATE ON mailbox_aliases
WHEN (NEW.target IS NOT OLD.target OR NEW.local_part IS NOT OLD.local_part OR NEW.kind IS NOT OLD.kind OR NEW.domain_id IS NOT OLD.domain_id) AND NEW.sender_logins IS OLD.sender_logins
BEGIN
  UPDATE mailbox_aliases SET sender_logins = '[]' WHERE id = NEW.id;
END;

-- Port of PG function urmail_archive_purge_guard (legal_hold 期间禁 purge；purge 仅限 30 天前已删且未 hold 的条目)
CREATE TRIGGER IF NOT EXISTS archive_hold_purge_guard
BEFORE UPDATE ON archive_entries
WHEN NEW.legal_hold AND EXISTS(SELECT 1 FROM archive_content WHERE entry_id = NEW.id AND (purge_started_at IS NOT NULL OR purged_at IS NOT NULL))
BEGIN
  SELECT RAISE(ABORT,'ARCHIVE_PURGE_STARTED');
END;

CREATE TRIGGER IF NOT EXISTS archive_content_purge_eligibility
BEFORE UPDATE ON archive_content
WHEN NEW.purge_started_at IS NOT NULL AND (OLD.purge_started_at IS NULL OR NEW.purged_at IS NOT OLD.purged_at) AND NOT EXISTS(SELECT 1 FROM archive_entries WHERE id = NEW.entry_id AND tenant_id = NEW.tenant_id AND NOT legal_hold AND deleted_at <= (CAST(strftime('%s','now') AS INTEGER) - 2592000)*1000000)
BEGIN
  SELECT RAISE(ABORT,'ARCHIVE_PURGE_INELIGIBLE');
END;

-- Port of PG function urmail_billing_profile_write_guard (billing_document_profile 身份不可变；写权限 role 判定为会话语义)
CREATE TRIGGER IF NOT EXISTS billing_profile_identity_immutable
BEFORE UPDATE ON settings
WHEN OLD.key = 'billing_document_profile' AND (NEW.key IS NOT OLD.key OR NEW.scope IS NOT OLD.scope OR NEW.scope_id IS NOT OLD.scope_id)
BEGIN
  SELECT RAISE(ABORT,'BILLING_PROFILE_IDENTITY_IMMUTABLE');
END;

-- APP-PENDING (urmail_billing_profile_write_guard): BILLING_PROFILE_FORBIDDEN（scope/tenant/owner-admin-billing role 判定）→ S2 装饰器

-- Port of PG function urmail_contact_group_member_guard (成员必须同租户/邮箱/通讯录且双方未删)
CREATE TRIGGER IF NOT EXISTS contact_group_member_scope
BEFORE INSERT ON mailbox_contact_group_members
WHEN NOT EXISTS(SELECT 1 FROM mailbox_contact_groups g JOIN mailbox_contacts c ON c.tenant_id = g.tenant_id AND c.mailbox_id = g.mailbox_id AND c.addressbook_id = g.addressbook_id WHERE g.tenant_id = NEW.tenant_id AND g.mailbox_id = NEW.mailbox_id AND g.id = NEW.group_id AND c.id = NEW.contact_id AND g.deleted_at IS NULL AND c.deleted_at IS NULL)
BEGIN
  SELECT RAISE(ABORT,'contact group scope mismatch');
END;

-- Port of PG function urmail_domain_provisioning_guard (app 写路径的 provisioning 状态冻结；dkim/mode 变更重置为 pending)
CREATE TRIGGER IF NOT EXISTS domain_provisioning_reset_on_dkim_change
AFTER UPDATE ON domains
WHEN (NEW.mode IS NOT OLD.mode OR NEW.dkim_selector IS NOT OLD.dkim_selector OR NEW.dkim_private_key IS NOT OLD.dkim_private_key) AND (NEW.provisioning_state IS NOT 'pending' OR NEW.dns_explicit IS NOT 0)
BEGIN
  UPDATE domains SET provisioning_state = 'pending', dns_explicit = 0 WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS domain_provisioning_insert_pending
AFTER INSERT ON domains
WHEN NEW.provisioning_state IS NOT 'pending' OR NEW.dns_explicit IS NOT 0 OR NEW.custom_web_enabled IS NOT 0
BEGIN
  UPDATE domains SET provisioning_state = 'pending', dns_explicit = 0, custom_web_enabled = 0 WHERE id = NEW.id;
END;

-- APP-PENDING (urmail_domain_provisioning_guard): DOMAIN_PROVISIONING_FORBIDDEN（role=platform/migrate 豁免与插入强制 pending 的角色分支）→ S2 装饰器（单引擎下 app 即全写方，插入强制 pending 保留在触发器）

-- Port of PG function urmail_guard_host_namespace (brand_hosts 与 domains 主机名互斥（忽略大小写与尾点）)
CREATE TRIGGER IF NOT EXISTS domains_host_namespace_guard__insert
BEFORE INSERT ON domains
WHEN EXISTS(SELECT 1 FROM brand_hosts WHERE lower(rtrim(hostname,'.')) = lower(rtrim(NEW.fqdn,'.')))
BEGIN
  SELECT RAISE(ABORT,'hostname is reserved by a brand host');
END;

CREATE TRIGGER IF NOT EXISTS domains_host_namespace_guard__update
BEFORE UPDATE ON domains
WHEN EXISTS(SELECT 1 FROM brand_hosts WHERE lower(rtrim(hostname,'.')) = lower(rtrim(NEW.fqdn,'.')))
BEGIN
